#include <iostream>
#include <string>
#include <exception>

int main() {
    std::string userInput = "123";  // Simulate input from a file or user
    try {
        int numericValue = std::stoi(userInput);  // Convert string to int
        std::cout << "Converted value: " << numericValue << std::endl;  // Output: 123
        // Real-world usage: Use this value for calculations or processing
    } catch (const std::invalid_argument& e) {
        std::cout << "Error: String is not a valid number." << std::endl;  // Best practice: Handle invalid input
    } catch (const std::out_of_range& e) {
        std::cout << "Error: Number is out of range for int." << std::endl;  // Avoid overflows
    }
    return 0;
}
